BEGIN TRANSACTION;
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(7122673, 1088978, 93565, '<td valign="top">Dragonflies are just the most frustrating size for macro, but this is quite an interesting take on things. I''d like a little more DoF, so we''d have the face in focus as well, but this is interesting. The background foliage on the left side of the image could''ve been toned down some too, as it''s rather distracting with the large blades of grass, but this is an interesting direction to take the shot.</td>', 'Dragonflies are just the most frustrating size for macro, but this is quite an interesting take on things. I''d like a little more DoF, so we''d have the face in focus as well, but this is interesting. The background foliage on the left side of the image could''ve been toned down some too, as it''s rather distracting with the large blades of grass, but this is an interesting direction to take the shot.', '2013-10-28 02:08:30.000000', NULL, 1),
(7122674, 1088525, 93565, '<td valign="top">Great detail but I find the positioning and composition lacking.</td>', 'Great detail but I find the positioning and composition lacking.', '2013-10-28 02:09:21.000000', NULL, 1),
(7122676, 1088977, 93565, '<td valign="top">lol<br/>Awesome. I appreciate the divergent path on insects. Curious as to where you stumbled upon such a bumper crop of maggots.</td>', 'lolAwesome. I appreciate the divergent path on insects. Curious as to where you stumbled upon such a bumper crop of maggots.', '2013-10-28 02:10:11.000000', NULL, 1),
(7122678, 1088401, 93565, '<td valign="top">I hate to be the hyper mega anal insect guy, but these are not beetles, strictly speaking. In any case, you''ve got an interesting find with them all so tightly clustered. There seems to be some oddness in the editing though, with strange multi colored bands on the left side in the middle.</td>', 'I hate to be the hyper mega anal insect guy, but these are not beetles, strictly speaking. In any case, you''ve got an interesting find with them all so tightly clustered. There seems to be some oddness in the editing though, with strange multi colored bands on the left side in the middle.', '2013-10-28 02:12:19.000000', NULL, 1),
(7122679, 1088404, 93565, '<td valign="top">Interesting composition and I like the third out of focus fly lurking in the back, as well.</td>', 'Interesting composition and I like the third out of focus fly lurking in the back, as well.', '2013-10-28 02:12:55.000000', NULL, 1),
(7122680, 1088817, 93565, '<td valign="top">Boxelder bugs are the only thing that was active in my neck of the woods as well, and I tried all manner of things to try and get an interesting "action" shot, but you managed quite well simply through using a pleasing environment.</td>', 'Boxelder bugs are the only thing that was active in my neck of the woods as well, and I tried all manner of things to try and get an interesting "action" shot, but you managed quite well simply through using a pleasing environment.', '2013-10-28 02:14:17.000000', NULL, 1),
(7122683, 1089039, 93565, '<td valign="top">This photo would benefit immensely from some increased DoF.</td>', 'This photo would benefit immensely from some increased DoF.', '2013-10-28 02:15:55.000000', NULL, 1),
(7122684, 1088741, 93565, '<td valign="top">Love the minimalism. Simple tones, obliterated details on everything but the spider. Great find, great shot. Top marks from me.</td>', 'Love the minimalism. Simple tones, obliterated details on everything but the spider. Great find, great shot. Top marks from me.', '2013-10-28 02:17:01.000000', NULL, 1),
(7122685, 1088755, 93565, '<td valign="top">Simple, but effective. Wonderfully rendered in bw.</td>', 'Simple, but effective. Wonderfully rendered in bw.', '2013-10-28 02:19:50.000000', NULL, 1),
(7122687, 1088883, 93565, '<td valign="top">Crustaceans are arthropods, but are neither arachnids nor insects. But, disregarding that (a frankly overly specific subject requirement imo), I''d love to have seen a shot of this guy''s eyes, which look like they''d be awesome for closeups, as well as a less static composition.</td>', 'Crustaceans are arthropods, but are neither arachnids nor insects. But, disregarding that (a frankly overly specific subject requirement imo), I''d love to have seen a shot of this guy''s eyes, which look like they''d be awesome for closeups, as well as a less static composition.', '2013-10-28 02:25:09.000000', NULL, 1),
(7122691, 1088596, 93565, '<td valign="top">I''ve still yet to see one of these in spite of being quite the insect hound. Curious what the specular highlights are from on the head/thorax? Nice shot, in any case.</td>', 'I''ve still yet to see one of these in spite of being quite the insect hound. Curious what the specular highlights are from on the head/thorax? Nice shot, in any case.', '2013-10-28 02:27:27.000000', NULL, 1),
(7122692, 1088960, 93565, '<td valign="top">The lighting does some to make this fellow stand out well, but I''d like to see him on a lighter colored background to really accentuate his body.</td>', 'The lighting does some to make this fellow stand out well, but I''d like to see him on a lighter colored background to really accentuate his body.', '2013-10-28 02:28:36.000000', NULL, 1),
(7122750, 1089090, 124190, '<td valign="top">This type of spider makes my skin crawl because they can jump and usually hide under carpets and my doggy''s outdoor water bowls..... yup.   Natural environment = lurking in those corners!</td>', 'This type of spider makes my skin crawl because they can jump and usually hide under carpets and my doggy''s outdoor water bowls..... yup.   Natural environment = lurking in those corners!', '2013-10-28 06:58:40.000000', NULL, 1),
(7122751, 1088935, 124190, '<td valign="top">Looks like he''s holding a cigar in his ........(shadow). My favorite.....</td>', 'Looks like he''s holding a cigar in his ........(shadow). My favorite.....', '2013-10-28 07:02:16.000000', NULL, 1),
(7122752, 1089089, 124190, '<td valign="top">Beautiful color contrasts!</td>', 'Beautiful color contrasts!', '2013-10-28 07:02:50.000000', NULL, 1),
(7122761, 1088766, 124190, '<td valign="top">Love the wing line blurs!  Bzzzzzzzzzzzzzzzz</td>', 'Love the wing line blurs!  Bzzzzzzzzzzzzzzzz', '2013-10-28 07:50:51.000000', NULL, 1),
(7122762, 1088874, 124190, '<td valign="top">Handsome fellow....should be enameled for posterity.</td>', 'Handsome fellow....should be enameled for posterity.', '2013-10-28 07:53:18.000000', NULL, 1),
(7122763, 1089031, 124190, '<td valign="top">Love the colors...composition...posture....lighting.</td>', 'Love the colors...composition...posture....lighting.', '2013-10-28 07:55:36.000000', NULL, 1),
(7122765, 1088977, 124190, '<td valign="top">Foul.  I tried sweeping them up once when my trash can had a hole in the bottom of it and I tossed raw meat out...left for vaca and came home to a garage floor covered with squirmers....eventually realized gasoline and a match worked better than sweeping them into a pile with a broom.....   where did you go for vaca.?  Lolol</td>', 'Foul.  I tried sweeping them up once when my trash can had a hole in the bottom of it and I tossed raw meat out...left for vaca and came home to a garage floor covered with squirmers....eventually realized gasoline and a match worked better than sweeping them into a pile with a broom.....   where did you go for vaca.?  Lolol', '2013-10-28 07:58:42.000000', NULL, 1),
(7122801, 1088741, 15711, '<td valign="top">Love the use of negative space!!</td>', 'Love the use of negative space!!', '2013-10-28 09:28:22.000000', NULL, 1),
(7122802, 1088651, 15711, '<td valign="top">Lovely.  That green bokeh is to die for!!</td>', 'Lovely.  That green bokeh is to die for!!', '2013-10-28 09:28:43.000000', NULL, 1),
(7122860, 1088830, 118154, '<td valign="top">Will be in the running for sure.</td>', 'Will be in the running for sure.', '2013-10-28 13:31:04.000000', NULL, 1),
(7122861, 1089030, 118154, '<td valign="top">Best in show, but I am not sure it will work out that way.</td>', 'Best in show, but I am not sure it will work out that way.', '2013-10-28 13:32:27.000000', NULL, 1),
(7122913, 1089030, 147247, '<td valign="top">Love the idea and the photo!</td>', 'Love the idea and the photo!', '2013-10-28 18:21:48.000000', NULL, 1),
(7122959, 1089103, 150277, '<td valign="top">You made me laugh.  The dragonfly was a bit difficult to see.</td>', 'You made me laugh.  The dragonfly was a bit difficult to see.', '2013-10-28 21:57:03.000000', NULL, 1),
(7122960, 1089096, 150277, '<td valign="top">Wow.  Beautiful capture, the butterfly is very sharp.  The color of the butterfly and the color of the background complement each other nicely.</td>', 'Wow.  Beautiful capture, the butterfly is very sharp.  The color of the butterfly and the color of the background complement each other nicely.', '2013-10-28 21:58:04.000000', NULL, 1),
(7122962, 1089034, 150277, '<td valign="top">Interesting perspective.  Freaky spider.  Nice sharpness on the legs.</td>', 'Interesting perspective.  Freaky spider.  Nice sharpness on the legs.', '2013-10-28 21:59:01.000000', NULL, 1),
(7122963, 1089030, 150277, '<td valign="top">I love it, although I missed some sort of color hinting at the content of the background the bug might be in.</td>', 'I love it, although I missed some sort of color hinting at the content of the background the bug might be in.', '2013-10-28 22:00:27.000000', NULL, 1),
(7122965, 1088741, 150277, '<td valign="top">He is a cute little guy.  It''s almost like you captured his expression of dismay that you are shooting him.  Pretty green background makes him stand out.</td>', 'He is a cute little guy.  It''s almost like you captured his expression of dismay that you are shooting him.  Pretty green background makes him stand out.', '2013-10-28 22:01:36.000000', NULL, 1),
(7122966, 1088955, 150277, '<td valign="top">I almost feel like he is going to jump off the screen right at me.  Scary.  Nice sharpness.</td>', 'I almost feel like he is going to jump off the screen right at me.  Scary.  Nice sharpness.', '2013-10-28 22:02:24.000000', NULL, 1),
(7122968, 1088819, 150277, '<td valign="top">This was interesting. I like the varying patterns on either side of the bug.  And his shadow is fearsome.</td>', 'This was interesting. I like the varying patterns on either side of the bug.  And his shadow is fearsome.', '2013-10-28 22:03:46.000000', NULL, 1),
(7122969, 1088964, 150277, '<td valign="top">Wonderful image.  I like the focal point and the hint of a shadow.</td>', 'Wonderful image.  I like the focal point and the hint of a shadow.', '2013-10-28 22:05:26.000000', NULL, 1),
(7122971, 1089090, 150277, '<td valign="top">Crying a little with fear.  I love the realism.</td>', 'Crying a little with fear.  I love the realism.', '2013-10-28 22:07:02.000000', NULL, 1),
(7122972, 1088032, 150277, '<td valign="top">Wonderfully timed photo.  I love that her expression seems of wonder and curiosity rather than fear.</td>', 'Wonderfully timed photo.  I love that her expression seems of wonder and curiosity rather than fear.', '2013-10-28 22:10:21.000000', NULL, 1),
(7122973, 1089058, 150277, '<td valign="top">Just an incredible photo.  I almost makes me think of a dog shaking but this is a tiny bug.  Beautiful lighting.</td>', 'Just an incredible photo.  I almost makes me think of a dog shaking but this is a tiny bug.  Beautiful lighting.', '2013-10-28 22:11:28.000000', NULL, 1),
(7123030, 1089058, 60173, '<td valign="top">I like what you''ve done here with the processing by embracing the far ends of light and dark. I assume the specks are dirt on the window that caught light? So cute and fluffy, yet so scary...</td>', 'I like what you''ve done here with the processing by embracing the far ends of light and dark. I assume the specks are dirt on the window that caught light? So cute and fluffy, yet so scary...', '2013-10-29 01:23:05.000000', NULL, 1),
(7123031, 1089031, 60173, '<td valign="top">Great simplicity. Bess looks like she''s trotting off to somewhere. I will say that I feel there could have been some better light on her side facing the camera. The blacks have lost some detail there. Overall though, I really, really like it.</td>', 'Great simplicity. Bess looks like she''s trotting off to somewhere. I will say that I feel there could have been some better light on her side facing the camera. The blacks have lost some detail there. Overall though, I really, really like it.', '2013-10-29 01:26:35.000000', NULL, 1),
(7123032, 1088149, 60173, '<td valign="top">This is very well shot, but I feel like it''s missing something in the background to push it to the next level. The background is really bland as is. Great job on the exposure of the ant though.</td>', 'This is very well shot, but I feel like it''s missing something in the background to push it to the next level. The background is really bland as is. Great job on the exposure of the ant though.', '2013-10-29 01:28:34.000000', NULL, 1),
(7123033, 1089090, 60173, '<td valign="top">Make it dead! ...and then clean your floorboards.  :)</td>', 'Make it dead! ...and then clean your floorboards.  :)', '2013-10-29 01:28:58.000000', NULL, 1),
(7123036, 1089089, 60173, '<td valign="top">I love these guys! You really caught it in great light too. I will say, however, it looks like you burned the bottom right corner? I think the fire of the caterpillar fuzz would have held its own without you putting the vignette-type effect on the photo. <br/> <br/>Was that corner blown by chance? I can see why you might want to burn it if it were blown out and white, but if that''s the case, I think you took it too far. To me that corner doesn''t have a natural look to it. It simply says, "I''ve been burned."</td>', 'I love these guys! You really caught it in great light too. I will say, however, it looks like you burned the bottom right corner? I think the fire of the caterpillar fuzz would have held its own without you putting the vignette-type effect on the photo.  Was that corner blown by chance? I can see why you might want to burn it if it were blown out and white, but if that''s the case, I think you took it too far. To me that corner doesn''t have a natural look to it. It simply says, "I''ve been burned."', '2013-10-29 01:34:54.000000', NULL, 1),
(7123038, 1088741, 60173, '<td valign="top">Oh hai! Cute little bugger. That''s an extremely narrow DOF, and you nailed it. Nice job. I like the composition and subtle colors also.</td>', 'Oh hai! Cute little bugger. That''s an extremely narrow DOF, and you nailed it. Nice job. I like the composition and subtle colors also.', '2013-10-29 01:38:39.000000', NULL, 1),
(7123039, 1089103, 60173, '<td valign="top">I would have cropped out the bushes, mainly because of the thing in the bushes on the left. Kind of a fun image in a Where''s Waldo sense. That dragonfly is very well camouflaged.</td>', 'I would have cropped out the bushes, mainly because of the thing in the bushes on the left. Kind of a fun image in a Where''s Waldo sense. That dragonfly is very well camouflaged.', '2013-10-29 01:41:04.000000', NULL, 1),
(7123179, 1089103, 94815, '<td valign="top">Something to ponder.</td>', 'Something to ponder.', '2013-10-29 13:56:37.000000', NULL, 1),
(7123182, 1089030, 167257, '<td valign="top">Lol</td>', 'Lol', '2013-10-29 14:01:11.000000', NULL, 1),
(7123183, 1088224, 167257, '<td valign="top">Lol</td>', 'Lol', '2013-10-29 14:02:35.000000', NULL, 1),
