(7123246, 1088596, 114225, '<td valign="top">Oh wow, that color is intense.</td>', 'Oh wow, that color is intense.', '2013-10-29 16:24:57.000000', NULL, 1),
(7123248, 1088473, 114225, '<td valign="top">Love how the green makes everything stand out.</td>', 'Love how the green makes everything stand out.', '2013-10-29 16:25:14.000000', NULL, 1),
(7123249, 1088766, 114225, '<td valign="top">Woah! That wing movement is cool!</td>', 'Woah! That wing movement is cool!', '2013-10-29 16:25:46.000000', NULL, 1),
(7123250, 1088958, 114225, '<td valign="top">I wish my strips worked that well...</td>', 'I wish my strips worked that well...', '2013-10-29 16:26:13.000000', NULL, 1),
(7123251, 1088955, 114225, '<td valign="top">Nice! Really looking into the heart of the beast.</td>', 'Nice! Really looking into the heart of the beast.', '2013-10-29 16:26:27.000000', NULL, 1),
(7123252, 1088741, 114225, '<td valign="top">I enjoy the composition of this.</td>', 'I enjoy the composition of this.', '2013-10-29 16:26:41.000000', NULL, 1),
(7123254, 1088960, 114225, '<td valign="top">Really camouflaged. Nicely done.</td>', 'Really camouflaged. Nicely done.', '2013-10-29 16:26:59.000000', NULL, 1),
(7123255, 1088872, 114225, '<td valign="top">That''s a really unique view of a butterfly.</td>', 'That''s a really unique view of a butterfly.', '2013-10-29 16:27:25.000000', NULL, 1),
(7123256, 1089029, 114225, '<td valign="top">Oh nice, I like the twist.</td>', 'Oh nice, I like the twist.', '2013-10-29 16:30:07.000000', NULL, 1),
(7123257, 1089089, 114225, '<td valign="top">Great color on this.</td>', 'Great color on this.', '2013-10-29 16:30:52.000000', NULL, 1),
(7123269, 1088828, 167257, '<td valign="top">I came back a third time.  Actually just noticed the face on the bug.  Raising your score!</td>', 'I came back a third time.  Actually just noticed the face on the bug.  Raising your score!', '2013-10-29 17:57:27.000000', NULL, 1),
(7123295, 1089058, 124982, '<td valign="top">Absolutely gorgeous! Love the unconventional use of B&amp;W, and together with the wonderful lighting and detail makes this image rock. Best in show!</td>', 'Absolutely gorgeous! Love the unconventional use of B&W, and together with the wonderful lighting and detail makes this image rock. Best in show!', '2013-10-29 18:35:29.000000', NULL, 1),
(7123296, 1088955, 124982, '<td valign="top">Beautiful lighting and detail. Wonderful macro. Top 3 for me!</td>', 'Beautiful lighting and detail. Wonderful macro. Top 3 for me!', '2013-10-29 18:35:51.000000', NULL, 1),
(7123298, 1088964, 124982, '<td valign="top">I want to like this, but something about the blur is "unnatural", as if you artificially blurred out the background in PP. Well, it''s not so much blurred as absent. Would be curious to see the original and compare.</td>', 'I want to like this, but something about the blur is "unnatural", as if you artificially blurred out the background in PP. Well, it''s not so much blurred as absent. Would be curious to see the original and compare.', '2013-10-29 18:37:19.000000', NULL, 1),
(7123299, 1088473, 124982, '<td valign="top">Lovely colors and sharpness. Wish we were in a little tighter with regard the crop, but still beautiful. Top 3 for me.</td>', 'Lovely colors and sharpness. Wish we were in a little tighter with regard the crop, but still beautiful. Top 3 for me.', '2013-10-29 18:37:51.000000', NULL, 1),
(7123332, 1089030, 163469, '<td valign="top">ha very clever...the best yet...I hope you win!!</td>', 'ha very clever...the best yet...I hope you win!!', '2013-10-29 22:05:04.000000', NULL, 1),
(7123333, 1088224, 163469, '<td valign="top">lol....ha very clever</td>', 'lol....ha very clever', '2013-10-29 22:05:43.000000', NULL, 1),
(7123738, 1088529, 69324, '<td valign="top">Not real sound technically, but has a certain aura about it.</td>', 'Not real sound technically, but has a certain aura about it.', '2013-10-30 22:41:53.000000', NULL, 1),
(7123741, 1089089, 69324, '<td valign="top">The backlighting worked well here, good catch</td>', 'The backlighting worked well here, good catch', '2013-10-30 22:47:22.000000', NULL, 1),
(7123745, 1088651, 69324, '<td valign="top">Has all the necessary elements for a quality macro. 9</td>', 'Has all the necessary elements for a quality macro. 9', '2013-10-30 22:53:46.000000', NULL, 1),
(7123747, 1088766, 69324, '<td valign="top">Tough catch in flight and in focus, nice work.</td>', 'Tough catch in flight and in focus, nice work.', '2013-10-30 22:55:27.000000', NULL, 1),
(7123799, 1088349, 124815, '<td valign="top"><strike></strike></td>', '', '2013-10-31 09:10:51.000000', NULL, 1),
(7123829, 1088633, 19944, '<td valign="top">So that''s what those little bastards look like up close.  I''m usually too busy crushing them to look.</td>', 'So that''s what those little bastards look like up close.  I''m usually too busy crushing them to look.', '2013-10-31 12:00:41.000000', NULL, 1),
(7123931, 1088955, 170281, '<td valign="top">Good framing and clarity.  Position of flower creates lines of focus to the insect.  Nicely done.</td>', 'Good framing and clarity.  Position of flower creates lines of focus to the insect.  Nicely done.', '2013-10-31 20:06:06.000000', NULL, 1),
(7123933, 1089096, 170281, '<td valign="top">Nice photo.  Very good coloring. Positioning of butterfly lower or higher following rule of thirds might have provided more effect.</td>', 'Nice photo.  Very good coloring. Positioning of butterfly lower or higher following rule of thirds might have provided more effect.', '2013-10-31 20:10:12.000000', NULL, 1),
(7123937, 1088978, 170281, '<td valign="top">Nice positioning and effect.  Hard to capture, I suspect.</td>', 'Nice positioning and effect.  Hard to capture, I suspect.', '2013-10-31 20:13:45.000000', NULL, 1),
(7123939, 1088755, 170281, '<td valign="top">Great use of rule of thirds and dramatic effect of black and white.  The simplicity and elegance of the shot outshines details of body features or flight.  Nicely done!</td>', 'Great use of rule of thirds and dramatic effect of black and white.  The simplicity and elegance of the shot outshines details of body features or flight.  Nicely done!', '2013-10-31 20:15:43.000000', NULL, 1),
(7123942, 1088149, 170281, '<td valign="top">Great framing; use of rule of thirds.  I am a fan of under-exposing a bit, but I suspect you would have lost some detail on the ant.  I love the simplicity. Nice work!</td>', 'Great framing; use of rule of thirds.  I am a fan of under-exposing a bit, but I suspect you would have lost some detail on the ant.  I love the simplicity. Nice work!', '2013-10-31 20:18:16.000000', NULL, 1),
(7123944, 1088763, 170281, '<td valign="top">Very nice positioning, color, and artistry brought on by the water drops.  Good job.</td>', 'Very nice positioning, color, and artistry brought on by the water drops.  Good job.', '2013-10-31 20:20:01.000000', NULL, 1),
(7123949, 1088977, 170281, '<td valign="top">This is a tough subject when in masses.  The uniformity of them all prevents dimension and artistic quality.  It may be my eyes, but it seems a bit out of focus.</td>', 'This is a tough subject when in masses.  The uniformity of them all prevents dimension and artistic quality.  It may be my eyes, but it seems a bit out of focus.', '2013-10-31 20:24:43.000000', NULL, 1),
(7123950, 1088883, 170281, '<td valign="top">I like these little critters, but I do not think it falls in the insect, bug, or beetle realm.  Use of rule of thirds would enhance photo.  Good clarity and coloring.</td>', 'I like these little critters, but I do not think it falls in the insect, bug, or beetle realm.  Use of rule of thirds would enhance photo.  Good clarity and coloring.', '2013-10-31 20:29:36.000000', NULL, 1),
(7123951, 1089017, 170281, '<td valign="top">Excellent framing and coloring.  Well done.</td>', 'Excellent framing and coloring.  Well done.', '2013-10-31 20:30:53.000000', NULL, 1),
(7123953, 1088900, 170281, '<td valign="top">I had to read the caption to see what was being captured.  At first the caterpillar looked like the plant to the left.  There is so much going around the caterpillar it is lost in the picture.  Maybe some cropping and reframing would enhance the photo.</td>', 'I had to read the caption to see what was being captured.  At first the caterpillar looked like the plant to the left.  There is so much going around the caterpillar it is lost in the picture.  Maybe some cropping and reframing would enhance the photo.', '2013-10-31 20:34:26.000000', NULL, 1),
