(7123963, 1088872, 170281, '<td valign="top">Excellent photo, from the coloring to the positioning.  Well done!</td>', 'Excellent photo, from the coloring to the positioning.  Well done!', '2013-10-31 20:55:18.000000', NULL, 1),
(7123964, 1088603, 170281, '<td valign="top">Very nice photo and editing.  Good color and framing.</td>', 'Very nice photo and editing.  Good color and framing.', '2013-10-31 20:56:18.000000', NULL, 1),
